import React,{useEffect,useMemo,useRef,useState}from'react';
import CycleTimeline from'./components/CycleTimeline.jsx';
import AgentPanel from'./components/AgentPanel.jsx';
const api=window.workspaceAgent;
const fmt=n=>new Intl.NumberFormat('fa-IR').format(n||0);
const bytes=n=>{if(!n)return'۰ B';const u=['B','KB','MB','GB','TB'];let i=0,v=n;while(v>=1024&&i<u.length-1){v/=1024;i++}return`${new Intl.NumberFormat('fa-IR',{maximumFractionDigits:1}).format(v)} ${u[i]}`};
const actionsForRole=c=>{const t=String(c?.element?.controlType||'');const a=['focus'];if(/Button|MenuItem|Hyperlink|ListItem|TabItem/.test(t))a.push('invoke');if(/CheckBox|RadioButton|ToggleButton/.test(t))a.push('toggle');if(/ComboBox|TreeItem|MenuItem/.test(t))a.push('expand','collapse');if(/Edit|Document|ComboBox/.test(t))a.push('setValue');if(c?.element?.canScrollIntoView)a.push('scrollIntoView');return [...new Set(a)]};
const tabs={home:'مرکز فرمان',agent:'دستیار هوشمند (Claude)',system:'اطلاعات ویندوز',explorer:'ابزارهای File Explorer',uia:'نقشه رابط ویندوز',mission:'ماموریت فارسی (قدیمی)',ai:'هوش مصنوعی محلی',health:'سلامت پوشه',intelligence:'تحلیل هوشمند',review:'صف بازبینی',zones:'Downloads و Desktop',drive:'مصرف دیسک',index:'ایندکس فایل‌ها',search:'جست‌وجوی فایل',cleanup:'پاک‌سازی امن',files:'مرتب‌سازی و تغییر نام',duplicates:'فایل‌های تکراری',snapshots:'مقایسه تغییرات',automation:'Automation',recovery:'بازیابی',watch:'File Watcher',cert:'گواهی‌سازی',pdf:'بررسی PDF',settings:'پشتیبان و تنظیمات',cycles:'تاریخچه عملیات'};
const navGroups=[
 {title:'شروع',items:['agent','files','search','duplicates','cleanup']},
 {title:'بررسی و گزارش',items:['health','drive','intelligence','pdf','zones','snapshots']},
 {title:'پیشرفته',advanced:true,items:['home','explorer','mission','ai','review','index','automation','watch','recovery','system','uia','cert','settings','cycles']}
];
const tabHints={agent:'به زبان ساده بگویید چه فایل‌هایی را پیدا و منظم کند؛ قبل از هر تغییر، طرح را می‌بینید و تأیید می‌کنید.',files:'مرتب‌سازی پوشه بر اساس نوع فایل و تغییر نام گروهی، با پیش‌نمایش.',search:'جست‌وجوی سریع فایل‌ها با نام، نوع و تاریخ.',duplicates:'پیدا کردن فایل‌های تکراری بدون حذف خودکار.',cleanup:'پاک‌سازی امن: فایل‌ها ابتدا به قرنطینه می‌روند و قابل بازگشتند.',health:'گزارش سلامت پوشه: فایل‌های بزرگ، قدیمی و زائد.',drive:'بررسی مصرف فضای دیسک.',intelligence:'تحلیل هوشمند محتوای پوشه.',pdf:'استخراج و بررسی متن PDFها.',zones:'نظارت بر Downloads و Desktop.',snapshots:'ذخیره وضعیت پوشه و مقایسه تغییرات بعدی.'};
export default function App(){
 const[tab,setTab]=useState('agent'),[showAdv,setShowAdv]=useState(false),[root,setRoot]=useState(''),[cycle,setCycle]=useState(null),[cycles,setCycles]=useState([]),[busy,setBusy]=useState(false),[health,setHealth]=useState(null),[dup,setDup]=useState(null),[caps,setCaps]=useState(null),[snaps,setSnaps]=useState([]),[command,setCommand]=useState(''),[goal,setGoal]=useState(null),[query,setQuery]=useState(''),[searchResult,setSearchResult]=useState(null),[rename,setRename]=useState({find:'',replace:'',prefix:'',suffix:'',sequence:false}),[system,setSystem]=useState(null),[rules,setRules]=useState([]),[ruleForm,setRuleForm]=useState({title:'بررسی دوره‌ای Workspace',cycleType:'workspace-health',intervalMinutes:60,conditionType:'always',threshold:10}),[intel,setIntel]=useState(null),[similarImages,setSimilarImages]=useState(null),[similarTexts,setSimilarTexts]=useState(null),[reviewItems,setReviewItems]=useState([]),[selectedReview,setSelectedReview]=useState([]),[zones,setZones]=useState([]),[zoneReport,setZoneReport]=useState(null),[activeZone,setActiveZone]=useState(null),[driveReport,setDriveReport]=useState(null),[recoveries,setRecoveries]=useState([]),[journalRows,setJournalRows]=useState([]),[journalStatus,setJournalStatus]=useState(null),[watches,setWatches]=useState([]),[watchEvents,setWatchEvents]=useState([]),[pdfReport,setPdfReport]=useState(null),[configPreview,setConfigPreview]=useState(null),[skills,setSkills]=useState(null),[uiaMap,setUiaMap]=useState(null),[uiaError,setUiaError]=useState(''),[indexStatus,setIndexStatus]=useState(null),[indexErrors,setIndexErrors]=useState([]),[indexHealth,setIndexHealth]=useState(null),[watchStatus,setWatchStatus]=useState(null),[resilience,setResilience]=useState(null),[certStatus,setCertStatus]=useState(null),[aiStatus,setAiStatus]=useState(null),[aiSettings,setAiSettings]=useState(null),[aiHealth,setAiHealth]=useState(null),[aiCommand,setAiCommand]=useState(''),[aiPlanResult,setAiPlanResult]=useState(null),[aiVision,setAiVision]=useState(null),[aiError,setAiError]=useState(''),[aiHardware,setAiHardware]=useState(null),[aiRuntime,setAiRuntime]=useState(null),[aiTrust,setAiTrust]=useState(null),[aiSelection,setAiSelection]=useState(null),[aiCapabilities,setAiCapabilities]=useState(null),[aiUiAssist,setAiUiAssist]=useState(null),[uiGroundIntent,setUiGroundIntent]=useState(''),[uiGrounding,setUiGrounding]=useState(null),[groundAction,setGroundAction]=useState('focus'),[groundValue,setGroundValue]=useState(''),[uiVisualVerify,setUiVisualVerify]=useState(null),[explorerForm,setExplorerForm]=useState({relativePath:'',query:'',sourceRelative:'',destinationRelative:'',newName:'',batchSources:'',batchDestination:'',batchDestinationRootToken:'',batchDestinationRootLabel:'Workspace فعلی',conflictPolicy:'skip',duplicateAware:true}),[explorerResult,setExplorerResult]=useState(null),[explorerError,setExplorerError]=useState(''),[rcCheck,setRcCheck]=useState(null),[diagResult,setDiagResult]=useState(null),[backupRows,setBackupRows]=useState([]),[backupPreview,setBackupPreview]=useState(null),[updateGuardState,setUpdateGuardState]=useState(null);
 const[batchAutoRunning,setBatchAutoRunning]=useState(false);
 const batchPumpRef=useRef({cycleId:'',mode:'idle',running:false});
 const refresh=async()=>setCycles(await api.cycles());
 const refreshSnaps=async r=>setSnaps(await api.snapshots(r||root));
 const refreshRules=async()=>setRules(await api.automationList());
 const refreshZones=async()=>setZones(await api.zonesList());
 const refreshRecovery=async()=>setRecoveries(await api.recoveryList());
 const refreshJournal=async()=>{setJournalRows(await api.journalList({limit:250}));setJournalStatus(await api.journalVerify())};
 const refreshWatches=async()=>{setWatches(await api.watchList());setWatchEvents(await api.watchEvents(250));setWatchStatus(await api.watchStatus());setResilience(await api.resilienceStatus())};
 const refreshCert=async()=>{const c=await api.certStatus();setCertStatus(c);setRcCheck(c?.rcSelfCheck||null);setUpdateGuardState(c?.updateGuard||null)};
 const refreshBackups=async()=>setBackupRows(await api.stateBackupList());
 const refreshAI=async()=>{const [status,settings,runtime,selection]=await Promise.all([api.aiStatus(),api.aiSettings(),api.aiRuntimeStatus(),api.aiRuntimeSelection()]);setAiStatus(status);setAiSettings(settings);setAiRuntime(runtime);setAiTrust(runtime?.trust||null);setAiSelection(selection)};
 const refreshReviews=async r=>{const target=r||root;if(!target){setReviewItems([]);return}setReviewItems(await api.reviewList(target));};
 const refreshIndex=async r=>{const target=r||root;if(!target){setIndexStatus(null);setIndexErrors([]);setIndexHealth(null);return}setIndexStatus(await api.indexStatus(target));setIndexErrors(await api.indexErrors(target,100));setIndexHealth(await api.indexHealth(false));};
 useEffect(()=>{refresh();refreshRules();refreshZones();refreshRecovery();refreshJournal();refreshWatches();refreshCert();refreshBackups();refreshAI();api.capabilities().then(setCaps);api.skills().then(setSkills)},[]);
 const indexReady=()=>!['not-indexed','unavailable'].includes(indexStatus?.status);
 async function doSearch(){if(indexReady())await run('indexed-file-search',{filters:{query},limit:500});else await run('file-search',{filters:{query}})}
 async function findDups(){if(indexReady())await run('indexed-duplicates');else await run('duplicates')}
 async function pick(){const p=await api.selectFolder();if(p){setRoot(p);setCycle(null);setHealth(null);setDup(null);setSearchResult(null);setIntel(null);setSimilarImages(null);setSimilarTexts(null);setSelectedReview([]);await refreshSnaps(p);await refreshReviews(p);await refreshIndex(p)}}
 async function run(type,input={}){const actualRoot=input.root||root;if(!actualRoot&&!['windows-system','windows-ui-map'].includes(type))return;setBusy(true);try{const c=await api.startCycle(type,{root:actualRoot,...input});setCycle(c);if(type==='workspace-health'&&c.result)setHealth(c.result);if((type==='duplicates'||type==='indexed-duplicates')&&c.result)setDup(c.result);if((type==='file-search'||type==='indexed-file-search')&&c.result)setSearchResult(c.result);if(type==='persistent-index-scan'||type==='persistent-index-maintenance')await refreshIndex(actualRoot);if(type==='windows-system'&&c.result)setSystem(c.result);if(type==='windows-ui-map'&&c.result)setUiaMap(c.result);if(type==='workspace-intelligence'&&c.result)setIntel(c.result);if(type==='similar-images'&&c.result)setSimilarImages(c.result);if(type==='similar-texts'&&c.result)setSimilarTexts(c.result);if(type==='managed-zone-audit'&&c.result)setZoneReport(c.result);if(type==='drive-audit'&&c.result)setDriveReport(c.result);if(type==='pdf-intelligence'&&c.result)setPdfReport(c.result);if(type==='review-queue-build'||type==='recommendation-apply')await refreshReviews(actualRoot);await refresh();await refreshRecovery();await refreshJournal();if(root)await refreshSnaps();return c}finally{setBusy(false)}}
 async function explorerRead(type,input={}){setExplorerError('');setExplorerResult(null);const c=await run(type,input);if(c?.result)setExplorerResult(c.result);else if(c?.ok===false)setExplorerError(c.message||c.code||'File Explorer Skill ناموفق بود.');return c}
 async function explorerWrite(type,input={}){if(!root)return;setExplorerError('');setBusy(true);try{const c=await api.startExplorerWrite(type,{root,...input});if(c?.id){setCycle(c);await refresh();await refreshRecovery();await refreshJournal();return c}setExplorerError(c?.message||c?.code||'Explorer Write Preview ساخته نشد.');return c}finally{setBusy(false)}}
 async function pickExplorerDestinationRoot(){setExplorerError('');const r=await api.explorerPickDestinationRoot();if(r?.ok)setExplorerForm(x=>({...x,batchDestinationRootToken:r.token,batchDestinationRootLabel:r.displayPath||'Root خارجی'}));else if(!r?.cancelled)setExplorerError(r?.message||r?.code||'انتخاب Root مقصد ناموفق بود.');}
 const isAutoBatchCheckpoint=c=>['explorer-batch-copy','explorer-batch-move'].includes(c?.type)&&c?.status==='paused'&&!c?.batchBlocker;
 async function explorerBatchPump(seed){if(!isAutoBatchCheckpoint(seed))return seed;const control=batchPumpRef.current;if(control.running)return seed;control.cycleId=seed.id;control.mode='run';control.running=true;setBatchAutoRunning(true);let current=seed;try{while(isAutoBatchCheckpoint(current)&&control.mode==='run'&&control.cycleId===current.id){await new Promise(r=>setTimeout(r,35));if(control.mode!=='run')break;const next=await api.explorerBatchResume(current.id);if(!next?.id){setExplorerError(next?.message||next?.code||'ادامه خودکار Batch ناموفق بود.');break}current=next;setCycle(current);if(current.batchBlocker)setExplorerError(`Batch در Checkpoint امن متوقف شد: ${current.batchBlocker.code||current.batchBlocker.category||'BLOCKED'}`)}if(control.mode==='cancel'&&current?.id&&['paused','interrupted'].includes(current.status)){const cancelled=await api.explorerBatchCancel(current.id);if(cancelled?.id){current=cancelled;setCycle(cancelled)}else setExplorerError(cancelled?.message||cancelled?.code||'Cancel ناموفق بود.')}await refresh();return current}catch(error){setExplorerError(error?.message||'خطا در ادامه خودکار Batch');return current}finally{control.running=false;if(control.cycleId===seed.id){control.mode='idle';control.cycleId=''}setBatchAutoRunning(false)}}
 function explorerBatchPauseAuto(id){const control=batchPumpRef.current;if(control.running&&control.cycleId===id)control.mode='pause';}
 async function explorerBatch(type){if(!root)return;const sources=String(explorerForm.batchSources||'').split(/\r?\n|,/).map(x=>x.trim()).filter(Boolean);if(!sources.length){setExplorerError('حداقل یک مسیر منبع برای Batch وارد کنید.');return}setExplorerError('');setBusy(true);try{const c=await api.startExplorerBatch(type,{root,sourcesRelative:sources,destinationRootToken:explorerForm.batchDestinationRootToken||'',destinationDirRelative:explorerForm.batchDestination,conflictPolicy:explorerForm.conflictPolicy,duplicateAware:explorerForm.duplicateAware,chunkSize:16,maxItems:50000,reserveBytes:256*1024*1024});if(c?.id){setCycle(c);if(explorerForm.batchDestinationRootToken)setExplorerForm(x=>({...x,batchDestinationRootToken:'',batchDestinationRootLabel:'Workspace فعلی'}));await refresh();return c}setExplorerError(c?.message||c?.code||'Batch Preview ساخته نشد.');return c}finally{setBusy(false)}}
 async function explorerBatchResume(id){const seed=cycle?.id===id?cycle:null;if(isAutoBatchCheckpoint(seed)){void explorerBatchPump(seed);return seed}setBusy(true);try{const c=await api.explorerBatchResume(id);if(c?.id){setCycle(c);if(isAutoBatchCheckpoint(c))setTimeout(()=>void explorerBatchPump(c),0)}else setExplorerError(c?.message||c?.code||'Resume ناموفق بود.');await refresh();return c}finally{setBusy(false)}}
 async function explorerBatchCancel(id){const control=batchPumpRef.current;if(control.running&&control.cycleId===id){control.mode='cancel';return cycle}setBusy(true);try{const c=await api.explorerBatchCancel(id);if(c?.id)setCycle(c);else setExplorerError(c?.message||c?.code||'Cancel ناموفق بود.');await refresh();return c}finally{setBusy(false)}}
 async function startUiaAction(target,action,value=''){setUiaError('');setBusy(true);try{const selector={processId:target.processId,windowName:uiaMap?.focusedWindow?.name||'',windowClassName:uiaMap?.focusedWindow?.className||'',automationId:target.automationId||'',name:target.name||'',className:target.className||'',controlType:target.controlType||'',frameworkId:target.frameworkId||''};const c=await api.startWindowsUiAction({action,selector,value,sensitive:false});if(c?.id){setCycle(c);await refresh();await refreshJournal();return c}setUiaError(c?.message||c?.code||'ساخت Action Preview ناموفق بود.');return c}catch(error){setUiaError(error?.message||'خطای UIA Action')}finally{setBusy(false)}}
 async function confirm(id,d){setBusy(true);try{const c=await api.confirmCycle(id,d);setCycle(c);if(c.type==='recommendation-apply')await refreshReviews(c.input?.root);await refresh();await refreshRecovery();await refreshJournal();if(root)await refreshSnaps();if(d==='approve'&&isAutoBatchCheckpoint(c))setTimeout(()=>void explorerBatchPump(c),0);return c}finally{setBusy(false)}}
 async function undo(id){setBusy(true);try{const r=await api.undoCycle(id);if(r.cycle){setCycle(r.cycle);if(r.cycle.type==='recommendation-apply')await refreshReviews(r.cycle.input?.root)}await refresh()}finally{setBusy(false)}}
 async function plan(){setGoal(await api.planGoal(command))}async function mission(){setGoal(null);return run('mission',{command})}
 async function saveAI(){if(!aiSettings)return;setAiError('');const r=await api.aiSettingsUpdate(aiSettings);if(r?.ok){setAiSettings(r.settings);await refreshAI()}else setAiError(r?.message||r?.code||'ذخیره تنظیمات Local AI ناموفق بود.')}
 async function testAI(){setAiError('');const r=await api.aiHealth();setAiHealth(r);if(!r?.ok)setAiError(r?.message||r?.code||'Local AI در دسترس نیست.')}
 async function makeAIPlan(){setAiError('');setAiPlanResult(null);if(!root||!aiCommand)return;setBusy(true);try{const r=await api.aiPlan(aiCommand,root);setAiPlanResult(r);if(!r?.ok)setAiError(r?.message||r?.code||'ساخت Local AI Plan ناموفق بود.')}finally{setBusy(false)}}
 async function executeAIPlan(){if(!aiPlanResult?.token||!root)return;setAiError('');setBusy(true);try{const c=await api.aiStartMission(aiPlanResult.token,root);if(c?.id){setCycle(c);setAiPlanResult(null);await refresh();await refreshJournal()}else setAiError(c?.message||c?.code||'اجرای AI Mission شروع نشد.')}finally{setBusy(false)}}
 async function runAIVision(){setAiError('');setBusy(true);try{const r=await api.aiVisionFile();if(r?.cancelled)return;setAiVision(r);if(!r?.ok)setAiError(r?.message||r?.code||'تحلیل Vision ناموفق بود.')}finally{setBusy(false)}}
 async function probeAIHardware(){setAiError('');setBusy(true);try{const r=await api.aiHardwareProfile(Boolean(aiSettings?.allowVision));if(r?.ok){setAiHardware(r.profile);if(!aiSettings?.runtimeThreads&&r.profile?.advice){const x=await api.aiApplyHardwareAdvice(r.profile.advice);if(x?.ok)setAiSettings(x.settings)}}else setAiError(r?.message||r?.code||'تشخیص سخت‌افزار ناموفق بود.')}finally{setBusy(false)}}
 async function pickAIRuntimeExe(){const r=await api.aiRuntimePickExecutable();if(r?.ok)setAiSettings(x=>({...x,runtimeExecutablePath:r.filePath}))}
 async function pickAIModel(){const r=await api.aiRuntimePickModel();if(r?.ok)setAiSettings(x=>({...x,runtimeModelPath:r.filePath}))}
 async function runtimeAction(kind){setAiError('');setBusy(true);try{const fn=kind==='start'?api.aiRuntimeStart:kind==='restart'?api.aiRuntimeRestart:api.aiRuntimeStop;const r=await fn();if(r?.ok){setAiRuntime(r.runtime);await refreshAI()}else setAiError(r?.message||r?.code||`Runtime ${kind} failed`)}finally{setBusy(false)}}
 async function inspectAIRuntimeTrust(){setAiError('');setBusy(true);try{const r=await api.aiRuntimeTrust();if(r?.ok)setAiTrust(r.trust);else{if(r?.trust)setAiTrust(r.trust);setAiError(r?.message||r?.code||'Runtime trust inspection failed')}}finally{setBusy(false)}}
 async function probeAICapabilities(includeVision=false){setAiError('');setBusy(true);try{const r=await api.aiCapabilityProbe(includeVision);setAiCapabilities(r);if(!r?.ok)setAiError(r?.message||r?.code||'Capability probe ناموفق بود.')}finally{setBusy(false)}}
 async function warmupAI(){setAiError('');setBusy(true);try{const r=await api.aiWarmup();if(!r?.ok)setAiError(r?.message||r?.code||'Warmup ناموفق بود.');else setAiHealth({ok:true,code:'AI_WARMED',latencyMs:r.latencyMs,models:[r.schema?.model].filter(Boolean)})}finally{setBusy(false)}}
 async function runAIUiAssist(){setAiError('');setAiUiAssist(null);setBusy(true);try{const r=await api.aiUiAssist();if(r?.cancelled){setAiUiAssist(r);return}setAiUiAssist(r);if(!r?.ok)setAiError(r?.message||r?.code||'UI Assist ناموفق بود.')}finally{setBusy(false)}}
 async function groundUiIntent(){setAiError('');setUiGrounding(null);setUiVisualVerify(null);if(!uiGroundIntent.trim())return;setBusy(true);try{const r=await api.aiGroundUi(uiGroundIntent);setUiGrounding(r);if(r?.ok&&r.result?.candidates?.[0]){const a=actionsForRole(r.result.candidates[0]);setGroundAction(a.includes('invoke')?'invoke':a[0]||'focus')}if(!r?.ok)setAiError(r?.message||r?.code||'Semantic UI Grounding ناموفق بود.')}finally{setBusy(false)}}
 async function groundUiWithVision(){if(!uiGrounding?.sessionToken)return;setAiError('');setBusy(true);try{const r=await api.aiGroundUiVision(uiGrounding.sessionToken);if(r?.cancelled)return;setUiGrounding(x=>({...x,...r}));if(!r?.ok)setAiError(r?.message||r?.code||'Vision corroboration ناموفق بود.')}finally{setBusy(false)}}
 async function startGroundedAction(candidate){if(!uiGrounding?.sessionToken||!candidate)return;setAiError('');setBusy(true);try{const allowed=actionsForRole(candidate);const action=allowed.includes(groundAction)?groundAction:(allowed[0]||'focus');const c=await api.startGroundedUiaAction({sessionToken:uiGrounding.sessionToken,candidateId:candidate.id,action,value:action==='setValue'?groundValue:''});if(c?.id){setCycle(c);setGroundAction(action);await refresh();await refreshJournal()}else setAiError(c?.message||c?.code||'Grounded Action Preview ساخته نشد.')}finally{setBusy(false)}}
 async function verifyCurrentUiaVisual(){if(!cycle?.id||cycle?.type!=='windows-ui-action')return;setAiError('');setBusy(true);try{const r=await api.aiVerifyUiaCycle(cycle.id);if(r?.cancelled)return;setUiVisualVerify(r);if(!r?.ok)setAiError(r?.message||r?.code||'Visual verification ناموفق بود.')}finally{setBusy(false)}}
 async function dismissReview(item,status='dismissed'){await api.reviewUpdate(item.id,{status});await refreshReviews();setSelectedReview(x=>x.filter(id=>id!==item.id))}
 async function auditZone(z){setActiveZone(z);setZoneReport(null);await run('managed-zone-audit',{root:z.root,zoneId:z.id})}
 const pending=useMemo(()=>reviewItems.filter(x=>x.status==='pending'),[reviewItems]);
 const rootTabs=['home','agent','mission','ai','health','intelligence','review','zones','drive','index','search','cleanup','files','duplicates','snapshots','automation','watch','pdf'];
 return <div className="app"><aside><div className="brand"><div className="orb">WA</div><div><b>Workspace Agent</b><small>مدیریت هوشمند فایل‌ها</small></div></div>{navGroups.map(g=>{const open=!g.advanced||showAdv||g.items.includes(tab);return <div className="navgroup" key={g.title}>{g.advanced?<button className="navtitle toggle" onClick={()=>setShowAdv(v=>!v)}>{g.title} {open?'▾':'◂'}</button>:<div className="navtitle">{g.title}</div>}{open&&g.items.filter(k=>tabs[k]).map(k=><button key={k} className={tab===k?'active':''} onClick={()=>setTab(k)}>{tabs[k]}</button>)}</div>})}<div className="safety"><b>امن به‌صورت پیش‌فرض</b><small>هیچ تغییری بدون پیش‌نمایش و تأیید شما انجام نمی‌شود، و حذف دائمی غیرفعال است.</small></div></aside><main><header><div><h1>{tabs[tab]}</h1><p>{tabHints[tab]||'Agent ویندوزی محلی برای مدیریت Workspace، دیسک و فایل‌ها.'}</p></div><span className="version">v1.0.0-rc1</span></header>
 {rootTabs.includes(tab)&&<section className="picker"><div><b>پوشه کاری</b><span>{root||'هنوز پوشه‌ای انتخاب نشده — اول یک پوشه انتخاب کنید'}</span></div><button className={root?'':'primary'} onClick={pick}>{root?'تغییر پوشه':'انتخاب پوشه…'}</button></section>}
 {tab==='home'&&<><div className="grid4"><Task title="Windows System" sub="OS / Disk / Startup Advisor" on={()=>{setTab('system');run('windows-system')}} disabled={false}/><Task title="File Explorer Skills" sub="Properties / Search / Copy / Move / Rename" on={()=>setTab('explorer')} disabled={false}/><Task title="Windows UI Map" sub="UI Automation / Focused controls" on={()=>{setTab('uia');run('windows-ui-map')}} disabled={false}/><Task title="Workspace Doctor" sub="Score / Large / Stale / Junk" on={()=>run('workspace-health')}/><Task title="Review Queue" sub="Suggestion → Select → Apply → Undo" on={()=>setTab('review')} disabled={false}/><Task title="Downloads / Desktop" sub="Managed Zones / Storage Trend" on={()=>setTab('zones')} disabled={false}/><Task title="Drive Audit" sub="User-data scan / System skip" on={()=>setTab('drive')} disabled={false}/><Task title="Persistent Index" sub="SQLite / Resume / Low RAM" on={()=>setTab('index')} disabled={false}/><Task title="Agent فارسی" sub="فرمان چندمرحله‌ای" on={()=>setTab('mission')} disabled={false}/><Task title="Local AI" sub="Qwen / llama.cpp · Plan-only" on={()=>setTab('ai')} disabled={false}/></div><CycleTimeline cycle={cycle} onConfirm={confirm} onUndo={undo}/>{caps&&<div className="panel"><div className="panel-title"><div><h3>Capability Registry</h3><p>تمرکز نسخه فعلی فقط روی قابلیت‌های Windows Agent و مدیریت امن فایل/دیسک است.</p></div><div className="mini-stats"><b>{fmt(caps.active)}</b><span>فعال/بتا</span><b>{fmt(caps.planned)}</b><span>Planned</span></div></div><div className="cap-grid">{caps.rows.map(c=><div className={`cap ${c.status}`} key={c.id}><div><b>{c.title}</b><span>{c.group} · {c.mode}</span></div><em>{c.status}</em><p>{c.detail}</p></div>)}</div></div>}{skills&&<div className="panel"><div className="panel-title"><div><h3>Reusable Skill Registry</h3><p>هر Mission فقط Skill ثبت‌شده را اجرا می‌کند؛ Write بدون Confirmation مجاز نیست.</p></div><div className="mini-stats"><b>{fmt(skills.read)}</b><span>Read</span><b>{fmt(skills.write)}</b><span>Write</span></div></div><div className="cap-grid">{skills.rows.map(x=><div className={`cap ${x.status}`} key={x.id}><div><b>{x.title}</b><span>{x.group} · {x.risk}</span></div><em>{x.skillId||x.id}</em><p>{x.cycleType} · {x.confirmation?'Confirm required':'No confirmation'}</p></div>)}</div></div>}</>}
 {tab==='system'&&<><div className="toolbar"><button className="primary large" onClick={()=>run('windows-system')} disabled={busy}>اجرای Windows System Doctor</button><span>Read-only؛ Startup Advisor فقط اولویت Review می‌دهد و Registry/Process را تغییر نمی‌دهد.</span></div><CycleTimeline cycle={cycle} onConfirm={confirm} onUndo={undo}/>{system&&<SystemReport data={system}/>}</>}
 {tab==='explorer'&&<><div className="panel"><div className="panel-title"><div><h3>File Explorer Skill Pack</h3><p>همه مسیرها نسبت به Workspace هستند. Readها بدون تغییر فایل؛ Writeها فقط Preview → Confirm → Execute → Verify.</p></div><b>v1.0.0-rc1</b></div><div className="formgrid"><input value={explorerForm.relativePath} onChange={e=>setExplorerForm(x=>({...x,relativePath:e.target.value}))} placeholder="مسیر نسبی، مثلاً docs/report.pdf"/><button onClick={()=>explorerRead('explorer-properties',{relativePath:explorerForm.relativePath})} disabled={!root||busy}>Properties</button><button onClick={()=>explorerRead('explorer-navigate',{relativePath:explorerForm.relativePath})} disabled={!root||busy}>Open in Explorer</button><button onClick={()=>explorerRead('explorer-select',{relativePath:explorerForm.relativePath})} disabled={!root||busy}>Reveal / Select</button></div><div className="formgrid"><input value={explorerForm.query} onChange={e=>setExplorerForm(x=>({...x,query:e.target.value}))} placeholder="Search query"/><button className="primary" onClick={()=>explorerRead('explorer-search',{query:explorerForm.query,limit:100})} disabled={!root||!explorerForm.query||busy}>Search</button></div>{explorerError&&<div className="action-error"><b>Explorer Skill متوقف شد</b><p>{explorerError}</p></div>}</div><div className="panel"><h3>Controlled Write Skills</h3><p>Writeهای تک‌آیتمی قبلی حفظ شده‌اند. برای Recursive/Batch از بخش Advanced Batch استفاده کنید؛ Symlink/Junction traversal همچنان مسدود است.</p><div className="formgrid"><input value={explorerForm.destinationRelative} onChange={e=>setExplorerForm(x=>({...x,destinationRelative:e.target.value}))} placeholder="مقصد نسبی؛ برای New Folder نام پوشه جدید"/><button onClick={()=>explorerWrite('explorer-new-folder',{destinationRelative:explorerForm.destinationRelative})} disabled={!root||!explorerForm.destinationRelative||busy}>Preview New Folder</button></div><div className="formgrid"><input value={explorerForm.sourceRelative} onChange={e=>setExplorerForm(x=>({...x,sourceRelative:e.target.value}))} placeholder="منبع نسبی"/><input value={explorerForm.destinationRelative} onChange={e=>setExplorerForm(x=>({...x,destinationRelative:e.target.value}))} placeholder="مقصد نسبی دقیق"/><button onClick={()=>explorerWrite('explorer-copy',{sourceRelative:explorerForm.sourceRelative,destinationRelative:explorerForm.destinationRelative})} disabled={!root||!explorerForm.sourceRelative||!explorerForm.destinationRelative||busy}>Preview Copy</button><button onClick={()=>explorerWrite('explorer-move',{sourceRelative:explorerForm.sourceRelative,destinationRelative:explorerForm.destinationRelative})} disabled={!root||!explorerForm.sourceRelative||!explorerForm.destinationRelative||busy}>Preview Move</button></div><div className="formgrid"><input value={explorerForm.sourceRelative} onChange={e=>setExplorerForm(x=>({...x,sourceRelative:e.target.value}))} placeholder="فایل/پوشه برای Rename"/><input value={explorerForm.newName} onChange={e=>setExplorerForm(x=>({...x,newName:e.target.value}))} placeholder="نام جدید فقط، بدون مسیر"/><button onClick={()=>explorerWrite('explorer-rename',{sourceRelative:explorerForm.sourceRelative,newName:explorerForm.newName})} disabled={!root||!explorerForm.sourceRelative||!explorerForm.newName||busy}>Preview Rename</button></div></div><div className="panel"><h3>Advanced Batch / Recursive Operations</h3><p>منابع همیشه نسبت به Workspace هستند. مقصد می‌تواند Workspace فعلی یا Rootی باشد که با Folder Picker امن انتخاب می‌کنی. Cross-volume Move با Copy → SHA-256 Verify → Delete Source انجام می‌شود.</p><div className="formgrid"><button onClick={pickExplorerDestinationRoot} disabled={!root||busy}>انتخاب Root مقصد خارجی</button><button onClick={()=>setExplorerForm(x=>({...x,batchDestinationRootToken:'',batchDestinationRootLabel:'Workspace فعلی'}))} disabled={busy}>مقصد = Workspace</button><small>{explorerForm.batchDestinationRootLabel}</small></div><textarea value={explorerForm.batchSources} onChange={e=>setExplorerForm(x=>({...x,batchSources:e.target.value}))} placeholder={'docs\nphotos\nreport.pdf'} rows={5}/><div className="formgrid"><input value={explorerForm.batchDestination} onChange={e=>setExplorerForm(x=>({...x,batchDestination:e.target.value}))} placeholder="پوشه مقصد نسبی، مثلاً archive"/><select value={explorerForm.conflictPolicy} onChange={e=>setExplorerForm(x=>({...x,conflictPolicy:e.target.value}))}><option value="skip">Conflict: Skip</option><option value="rename">Conflict: Rename</option><option value="replace">Conflict: Replace file</option></select><label><input type="checkbox" checked={explorerForm.duplicateAware} onChange={e=>setExplorerForm(x=>({...x,duplicateAware:e.target.checked}))}/> Duplicate-aware SHA-256</label></div><div className="actions"><button className="primary" onClick={()=>explorerBatch('explorer-batch-copy')} disabled={!root||!explorerForm.batchSources||!explorerForm.batchDestination||busy}>Preview Batch / Recursive Copy</button><button onClick={()=>explorerBatch('explorer-batch-move')} disabled={!root||!explorerForm.batchSources||!explorerForm.batchDestination||busy}>Preview Batch Move</button></div></div><CycleTimeline cycle={cycle} onConfirm={confirm} onUndo={undo} onResume={explorerBatchResume} onCancel={explorerBatchCancel} onPauseAuto={explorerBatchPauseAuto} autoRunning={batchAutoRunning&&batchPumpRef.current.cycleId===cycle?.id}/>{explorerResult&&<ExplorerResult data={explorerResult}/>}</>}
 {tab==='uia'&&<><div className="toolbar"><button className="primary large" onClick={()=>{setUiaError('');run('windows-ui-map')}} disabled={busy}>خواندن UI پنجره فعال</button><span>Grounding خواندنی + Action کنترل‌شده با Preview/Confirm/Pin/Verify؛ بدون coordinate click، SendKeys عمومی یا Password write.</span></div>{uiaError&&<div className="panel action-error"><b>Action متوقف شد</b><p>{uiaError}</p></div>}<CycleTimeline cycle={cycle} onConfirm={confirm} onUndo={undo}/>{uiaMap&&<UiaReport data={uiaMap} onAction={startUiaAction} busy={busy}/>}</>}
 {tab==='agent'&&<AgentPanel api={api} root={root}/>}
 {tab==='mission'&&<><div className="panel"><h3>فرمان فارسی</h3><textarea className="command" value={command} onChange={e=>setCommand(e.target.value)} placeholder="مثلاً: این پوشه رو هوشمند بررسی کن، پیشنهادها رو برای Review آماده کن و چیزی رو خودکار تغییر نده"/><div className="actions"><button onClick={plan} disabled={!command}>فقط ساخت Plan</button><button className="primary" onClick={mission} disabled={!root||!command||busy}>اجرای Mission</button></div>{goal&&<div className="preview-box"><b>{goal.summary}</b><p>Confidence: {Math.round(goal.confidence*100)}%</p>{goal.notes?.map((n,i)=><small key={i}>{n}</small>)}{goal.steps.map(s=><div className="preview-row" key={s.id}><span>{s.label}</span><small>{s.type} · {s.requiresConfirmation?'نیازمند تأیید':'Read-only/Local'}</small></div>)}</div>}</div><CycleTimeline cycle={cycle} onConfirm={confirm} onUndo={undo}/></>}
 {tab==='ai'&&<><div className="health-grid"><div className="panel"><div className="panel-title"><div><h3>Local AI Runtime</h3><p>External loopback endpoint یا Managed llama-server؛ مدل هیچ Tool اجرایی مستقیم دریافت نمی‌کند.</p></div><button onClick={refreshAI}>Refresh</button></div>{aiStatus&&<><div className="meter"><span>AI</span><b>{aiStatus.enabled?'Enabled':'Disabled'}</b></div><div className="meter"><span>Model</span><b>{aiStatus.model||'تنظیم نشده'}</b></div><div className="meter"><span>Runtime</span><b>{aiRuntime?.managed?`${aiRuntime.state} · ${aiRuntime.pid||'-'}`:'External / manual'}</b></div><div className="meter"><span>Circuit</span><b>{aiStatus.guard?.circuitOpen?'OPEN':'Closed'}</b></div><div className="meter"><span>Privacy</span><b>Loopback · no raw prompt · no background screenshot</b></div></>}</div><div className="panel"><h3>Hardware Advisor</h3><p>RAM/CPU و روی Windows اطلاعات WMI GPU خوانده می‌شود. VRAM WMI فقط سیگنال کم‌اعتماد است و Fit تضمین نمی‌شود.</p><div className="actions"><button onClick={probeAIHardware} disabled={busy}>Probe Hardware</button>{aiHardware?.advice&&<button onClick={async()=>{const r=await api.aiApplyHardwareAdvice(aiHardware.advice);if(r?.ok){setAiSettings(r.settings);await refreshAI()}}}>اعمال تنظیمات Runtime پیشنهادی</button>}</div>{aiHardware&&<><div className="meter"><span>RAM</span><b>{bytes(aiHardware.memory?.totalBytes)}</b></div><div className="meter"><span>CPU</span><b>{aiHardware.cpu?.logicalCores||'-'} threads</b></div><div className="meter"><span>GPU</span><b>{(aiHardware.gpus||[]).map(g=>g.name).join(' · ')||'نامشخص'}</b></div><div className="meter"><span>Suggested</span><b>{aiHardware.advice?.modelFamily} · ctx {fmt(aiHardware.advice?.contextSize)}</b></div><small>{aiHardware.advice?.note}</small></>}</div><div className="panel wide"><h3>Managed llama.cpp Runtime</h3><p>Agent فقط فایل <code>llama-server</code> و مدل <code>.gguf</code> انتخاب‌شده توسط کاربر را با آرگومان‌های allowlisted اجرا می‌کند. Host همیشه 127.0.0.1 و Web UI خاموش است. قبل از Spawn، SHA-256 و در Windows وضعیت Authenticode بررسی می‌شود.</p>{aiTrust&&<div className="preview-box"><b>Runtime Trust: {aiTrust.allowed?'ALLOWED':'BLOCKED'} · {aiTrust.code}</b><small>SHA-256: {aiTrust.sha256||'-'} {aiTrust.hashMatch?'· PIN MATCH':''}</small><small>Signer: {aiTrust.signer?.status||'not inspected'} · {aiTrust.signer?.subject||'-'} · {aiTrust.signer?.thumbprint||'-'}</small></div>}{aiSettings&&<div className="formgrid"><label><span>Managed Runtime</span><input type="checkbox" checked={Boolean(aiSettings.managedRuntime)} onChange={e=>setAiSettings({...aiSettings,managedRuntime:e.target.checked})}/></label><label><span>Start with Agent</span><input type="checkbox" checked={Boolean(aiSettings.runtimeStartOnLaunch)} onChange={e=>setAiSettings({...aiSettings,runtimeStartOnLaunch:e.target.checked})}/></label><div className="inline"><input value={aiSettings.runtimeExecutablePath||''} readOnly placeholder="llama-server.exe"/><button onClick={pickAIRuntimeExe}>انتخاب Runtime</button></div><div className="inline"><input value={aiSettings.runtimeModelPath||''} readOnly placeholder="model.gguf"/><button onClick={pickAIModel}>انتخاب GGUF</button></div><label><span>Port</span><input type="number" value={aiSettings.runtimePort||8080} onChange={e=>setAiSettings({...aiSettings,runtimePort:Number(e.target.value)})}/></label><label><span>Context</span><input type="number" value={aiSettings.runtimeContextSize||8192} onChange={e=>setAiSettings({...aiSettings,runtimeContextSize:Number(e.target.value)})}/></label><label><span>CPU Threads (0=auto)</span><input type="number" value={aiSettings.runtimeThreads||0} onChange={e=>setAiSettings({...aiSettings,runtimeThreads:Number(e.target.value)})}/></label><label><span>GPU Layers</span><select value={String(aiSettings.runtimeGpuLayers||'auto')} onChange={e=>setAiSettings({...aiSettings,runtimeGpuLayers:e.target.value})}><option value="auto">auto</option><option value="all">all</option><option value="0">CPU only</option></select></label><label><span>Runtime Trust Policy</span><select value={aiSettings.runtimeTrustMode||'inspect'} onChange={e=>setAiSettings({...aiSettings,runtimeTrustMode:e.target.value})}><option value="inspect">Inspect only</option><option value="hash-required">Require SHA-256 pin</option><option value="hash-and-signer-required">Require SHA-256 + Authenticode signer</option></select></label><input value={aiSettings.runtimeExpectedSha256||''} onChange={e=>setAiSettings({...aiSettings,runtimeExpectedSha256:e.target.value})} placeholder="Expected llama-server SHA-256 (64 hex)"/><input value={aiSettings.runtimeExpectedSignerThumbprint||''} onChange={e=>setAiSettings({...aiSettings,runtimeExpectedSignerThumbprint:e.target.value})} placeholder="Expected Authenticode signer thumbprint"/><div className="actions"><button onClick={saveAI}>ذخیره تنظیمات</button><button onClick={inspectAIRuntimeTrust} disabled={busy||!aiSettings.runtimeExecutablePath||!aiSettings.runtimeModelPath}>Verify Runtime Trust</button><button className="primary" disabled={busy||!aiSettings.managedRuntime} onClick={()=>runtimeAction('start')}>Start</button><button disabled={busy||!aiSettings.managedRuntime} onClick={()=>runtimeAction('restart')}>Restart</button><button disabled={busy} onClick={()=>runtimeAction('stop')}>Stop</button></div></div>}{aiSelection&&<p>{aiSelection.ok?`Model ${aiSelection.modelFile} · ${bytes(aiSelection.modelBytes)} · RAM ratio ${Math.round((aiSelection.ramRatio||0)*100)}%`:`Selection: ${aiSelection.error?.code||'ناقص'}`} {aiSelection.warning||''}</p>}{aiRuntime?.logs?.length>0&&<details><summary>آخرین Runtime Logهای حافظه‌ای</summary><pre className="preview-box">{aiRuntime.logs.slice(-12).map(x=>`${x.kind}: ${x.text}`).join('\n')}</pre></details>}</div><div className="panel"><h3>Provider + Capability</h3>{aiSettings&&<div className="formgrid"><label><span>Enable Local AI</span><input type="checkbox" checked={Boolean(aiSettings.enabled)} onChange={e=>setAiSettings({...aiSettings,enabled:e.target.checked})}/></label><label><span>Enable Vision</span><input type="checkbox" checked={Boolean(aiSettings.allowVision)} onChange={e=>setAiSettings({...aiSettings,allowVision:e.target.checked})}/></label><input value={aiSettings.baseUrl||''} onChange={e=>setAiSettings({...aiSettings,baseUrl:e.target.value})} placeholder="http://127.0.0.1:8080/v1"/><input value={aiSettings.model||''} onChange={e=>setAiSettings({...aiSettings,model:e.target.value})} placeholder="Model id / managed alias"/><div className="actions"><button onClick={saveAI}>ذخیره</button><button onClick={testAI}>Health</button><button onClick={warmupAI}>Warmup</button><button onClick={()=>probeAICapabilities(false)}>Probe JSON</button><button disabled={!aiSettings.allowVision} onClick={()=>probeAICapabilities(true)}>Probe Vision</button></div></div>}{aiHealth&&<p>{aiHealth.ok?`READY · ${aiHealth.latencyMs} ms · ${(aiHealth.models||[]).slice(0,3).join(', ')}`:`${aiHealth.code||'UNAVAILABLE'} · ${aiHealth.message||''}`}</p>}{aiCapabilities&&<div className="preview-box"><b>Capability Probe: {aiCapabilities.ok?'PASS':'CHECK'}</b><small>Schema JSON: {aiCapabilities.schemaJson?.ok?'OK':'NO'} · Vision advertised: {aiCapabilities.vision?.supported?'YES':'NO'} · Vision tested: {aiCapabilities.vision?.tested?(aiCapabilities.vision?.ok?'PASS':'FAIL'):'NO'}</small><small>Context: {fmt(aiCapabilities.props?.contextSize||0)} · Slots: {fmt(aiCapabilities.props?.totalSlots||0)} · Build: {aiCapabilities.props?.buildInfo||'-'}</small></div>}</div><div className="panel wide"><h3>Schema-constrained AI Planner</h3><p>Local AI فقط Skillهای allowlisted را پیشنهاد می‌دهد؛ Root/Path/Shell از خروجی مدل حذف می‌شود و Writeها Confirmation مستقل دارند.</p><textarea className="command" value={aiCommand} onChange={e=>setAiCommand(e.target.value)} placeholder="مثلاً: فایل‌های تکراری را بررسی کن، بعد یک برنامه امن برای مرتب‌سازی بر اساس نوع بساز"/><div className="actions"><button className="primary" disabled={!root||!aiCommand||busy||!aiStatus?.enabled} onClick={makeAIPlan}>ساخت Local AI Plan</button><button disabled={busy||!aiSettings?.allowVision} onClick={runAIVision}>Vision روی تصویر انتخابی</button><button disabled={busy||!aiSettings?.allowVision} onClick={runAIUiAssist}>UIA-first / Vision fallback</button></div>{aiError&&<p className="error">{aiError}</p>}{aiPlanResult?.ok&&<div className="preview-box"><b>{aiPlanResult.goalPlan?.summary}</b><p>Model: {aiPlanResult.model} · {aiPlanResult.latencyMs} ms · Confidence {Math.round((aiPlanResult.goalPlan?.confidence||0)*100)}%</p>{(aiPlanResult.goalPlan?.notes||[]).map((n,i)=><small key={i}>{n}</small>)}{(aiPlanResult.goalPlan?.steps||[]).map(s=><div className="preview-row" key={s.id}><span>{s.label}</span><small>{s.skillId} · {s.requiresConfirmation?'Write / Confirm':'Read-only/Local'}</small></div>)}<button className="primary" disabled={busy} onClick={executeAIPlan}>اجرای دقیق همین Plan</button><small>Plan token ده دقیقه اعتبار دارد و به Workspace فعلی bind شده است.</small></div>}</div>{aiVision?.ok&&<div className="panel wide"><h3>Local Vision Advisory</h3><p>{aiVision.summary}</p><small>{aiVision.fileLabel} · {aiVision.model} · {aiVision.latencyMs} ms</small>{(aiVision.warnings||[]).map((w,i)=><p key={i}>{w}</p>)}{(aiVision.elements||[]).slice(0,30).map((x,i)=><div className="file-row" key={`${x.label}-${i}`}><b>{Math.round(x.confidence*100)}%</b><span>{x.label} · {x.role}</span></div>)}</div>}{aiUiAssist?.ok&&<div className="panel wide"><h3>UI Assist</h3><p>Source: <b>{aiUiAssist.source}</b> · {aiUiAssist.reason}</p><small>Policy: UIA first · هیچ Screenshot خودکاری گرفته نمی‌شود.</small>{aiUiAssist.source==='uia'?<p>{fmt(aiUiAssist.uia?.elements?.length)} کنترل از UI Automation کافی بود؛ Vision فراخوانی نشد.</p>:<p>{aiUiAssist.vision?.summary}</p>}</div>}<div className="panel wide"><h3>Intelligent UI Grounding</h3><p>هدف را با زبان طبیعی بگو. UIA Candidate می‌سازد؛ Vision فقط همان Candidateها را تأیید/رد می‌کند و Target یا coordinate جدید نمی‌سازد.</p><div className="formgrid"><input value={uiGroundIntent} onChange={e=>setUiGroundIntent(e.target.value)} placeholder="مثلاً: دکمه ذخیره تنظیمات را پیدا کن"/><div className="actions"><button className="primary" disabled={busy||!uiGroundIntent.trim()} onClick={groundUiIntent}>Ground با UIA</button><button disabled={busy||!uiGrounding?.ok||!aiSettings?.allowVision} onClick={groundUiWithVision}>Vision corroboration</button></div></div>{uiGrounding?.ok&&<><div className="mini-stats"><b>{Math.round((uiGrounding.result?.topConfidence||0)*100)}%</b><span>Top confidence</span><b>{uiGrounding.result?.quality||'-'}</b><span>Quality</span><b>{uiGrounding.result?.visionUsed?'YES':'NO'}</b><span>Vision fused</span></div><div className="formgrid"><label><span>Action فقط با انتخاب کاربر</span><select value={groundAction} onChange={e=>setGroundAction(e.target.value)}><option value="focus">focus</option><option value="invoke">invoke</option><option value="toggle">toggle</option><option value="expand">expand</option><option value="collapse">collapse</option><option value="scrollIntoView">scrollIntoView</option><option value="setValue">setValue</option></select></label>{groundAction==='setValue'&&<input value={groundValue} maxLength={2048} onChange={e=>setGroundValue(e.target.value)} placeholder="مقدار غیرحساس"/>}</div>{(uiGrounding.result?.candidates||[]).map((c,i)=><div className="uia-row" key={c.id}><div><b>#{i+1} · {c.element?.name||'(بدون Name)'}</b><small>{c.element?.controlType} · {c.element?.surfaceKind||'window'} · semantic {Math.round((c.semanticScore||0)*100)}% · context {Math.round((c.contextScore||0)*100)}% · {c.element?.isOffscreen?'offscreen · ':''}{c.vision?.matched?`vision ${Math.round((c.vision.confidence||0)*100)}%`:'UIA only'}</small></div><div className="uia-actions"><span>{Math.round(((c.fusedConfidence??c.confidence)||0)*100)}%</span><button disabled={busy||!actionsForRole(c).includes(groundAction)} onClick={()=>startGroundedAction(c)}>Preview همین Candidate</button></div></div>)}</>}{cycle?.type==='windows-ui-action'&&cycle?.status==='completed'&&<div className="preview-box"><b>Post-action verification</b><small>UIA verification قبلاً انجام شده؛ این مرحله فقط corroboration تصویری روی Screenshot انتخابی است.</small><button disabled={busy||!aiSettings?.allowVision} onClick={verifyCurrentUiaVisual}>Visual Verify آخرین UI Action</button>{uiVisualVerify?.ok&&<small>نتیجه: {uiVisualVerify.visual?.result||'deterministic'} · {Math.round((uiVisualVerify.visual?.confidence||0)*100)}% · overall {uiVisualVerify.overall||'-'}</small>}</div>}</div></div><CycleTimeline cycle={cycle} onConfirm={confirm} onUndo={undo}/></>}
 {tab==='health'&&<><div className="toolbar"><button className="primary large" onClick={()=>run('workspace-health')} disabled={!root||busy}>تحلیل کامل Workspace</button></div><CycleTimeline cycle={cycle} onConfirm={confirm} onUndo={undo}/>{health&&<Health data={health}/>}</>}
 {tab==='intelligence'&&<><div className="grid4"><Task title="Workspace Intelligence" sub="Project / Destination / Rename" on={()=>run('workspace-intelligence')}/><Task title="Similar Photos" sub="dHash perceptual · Read-only" on={()=>run('similar-images')}/><Task title="Similar Texts" sub="SimHash content · Read-only" on={()=>run('similar-texts')}/><Task title="Build Review Queue" sub="Confidence ≥ 72% · Local only" on={async()=>{await run('review-queue-build');setTab('review')}}/><Task title="PDF Intelligence" sub="Metadata / Base text · No OCR" on={()=>run('pdf-intelligence')}/></div><div className="panel"><h3>Policy</h3><p>Intelligence فقط پیشنهاد می‌سازد. اعمال پیشنهاد فقط از Review Queue و پس از انتخاب، Preview و تأیید کاربر امکان‌پذیر است.</p></div><CycleTimeline cycle={cycle} onConfirm={confirm} onUndo={undo}/>{intel&&<IntelligenceReport data={intel}/>} {similarImages&&<SimilarityReport title="عکس‌های مشابه" data={similarImages} kind="image"/>} {similarTexts&&<SimilarityReport title="متن‌های مشابه" data={similarTexts} kind="text"/>}</>}
 {tab==='review'&&<><div className="toolbar"><button className="primary" onClick={()=>run('review-queue-build')} disabled={!root||busy}>بازسازی Review Queue</button><button onClick={()=>setSelectedReview(pending.filter(x=>x.confidence>=.9).map(x=>x.id))} disabled={!pending.length}>انتخاب High Confidence</button><button onClick={()=>setSelectedReview(pending.map(x=>x.id))} disabled={!pending.length}>انتخاب همه Pending</button><button className="primary" onClick={()=>run('recommendation-apply',{itemIds:selectedReview})} disabled={!selectedReview.length||busy}>Preview اجرای {fmt(selectedReview.length)} پیشنهاد</button><button onClick={async()=>{await api.reviewClear(root);await refreshReviews()}} disabled={!root}>پاک‌سازی Dismissed/Reverted از صف</button></div><div className="panel"><div className="panel-title"><div><h3>Recommendation Review Queue</h3><p>Move و Rename یک فایل در زمان Preview با هم ترکیب می‌شوند. Collision Guard و Staging فعال است.</p></div><div className="mini-stats"><b>{fmt(pending.length)}</b><span>Pending</span><b>{fmt(reviewItems.filter(x=>x.status==='applied').length)}</b><span>Applied</span></div></div>{reviewItems.map(x=><div className={`review-row ${x.status}`} key={x.id}><label><input type="checkbox" disabled={x.status!=='pending'} checked={selectedReview.includes(x.id)} onChange={e=>setSelectedReview(s=>e.target.checked?[...new Set([...s,x.id])]:s.filter(id=>id!==x.id))}/><span><b>{x.actionType==='move'?'Move':'Rename'} · {x.status}</b><button className="linkish" onClick={()=>api.showItem(x.source)}>{x.source}</button><small>→ {x.actionType==='move'?x.suggestedFolder:x.suggestedName}</small></span></label><Confidence value={x.confidence}/><p>{(x.evidence||[]).join(' · ')}</p><div className="actions">{x.status==='pending'&&<button onClick={()=>dismissReview(x)}>Dismiss</button>}{x.status==='dismissed'&&<button onClick={()=>dismissReview(x,'pending')}>برگرداندن به Pending</button>}</div></div>)}{!reviewItems.length&&<p>صف خالی است. ابتدا Workspace Intelligence را اجرا و سپس Review Queue را بسازید.</p>}</div><CycleTimeline cycle={cycle} onConfirm={confirm} onUndo={undo}/></>}
 {tab==='zones'&&<><div className="toolbar"><button className="primary" disabled={!root} onClick={async()=>{await api.zonesAdd({root,title:'Workspace سفارشی',type:'custom'});await refreshZones()}}>افزودن Workspace فعلی به Managed Zones</button><span>Downloads / Desktop / Documents به‌صورت Built-in شناخته می‌شوند.</span></div><div className="panel"><h3>Managed Zones</h3>{zones.map(z=><div className="zone-row" key={z.id}><div><b>{z.title}</b><small>{z.type} · {z.root}</small></div><div className="actions"><button onClick={()=>api.openPath(z.root)}>باز کردن</button><button className="primary" onClick={()=>auditZone(z)} disabled={busy}>Audit</button>{!z.builtIn&&<button className="danger" onClick={async()=>{await api.zonesRemove(z.id);await refreshZones()}}>حذف Zone</button>}</div></div>)}</div><CycleTimeline cycle={cycle} onConfirm={confirm} onUndo={undo}/>{zoneReport&&<ZoneReport data={zoneReport} zone={activeZone}/>}</>}
 {tab==='drive'&&<><div className="panel note"><h3>Drive-wide Audit</h3><p>روی Windows، Agent از Workspace انتخاب‌شده ریشه همان Drive را پیدا می‌کند. Windows / Program Files / ProgramData / Recovery و پوشه‌های سیستمی از اسکن عمیق کنار گذاشته می‌شوند. این چرخه Read-only است.</p></div><div className="toolbar"><button className="primary large" onClick={()=>run('drive-audit')} disabled={!root||busy}>Audit درایو Workspace</button></div><CycleTimeline cycle={cycle} onConfirm={confirm} onUndo={undo}/>{driveReport&&<DriveReport data={driveReport}/>}</>}
 {tab==='index'&&<><div className="panel note"><h3>Persistent SQLite File Index</h3><p>اسکن streaming و قابل Resume با SQLite WAL؛ Hash سنگین Duplicate خارج از Main Thread اجرا می‌شود. Maintenance فقط دیتای داخلی Agent را بررسی/بهینه می‌کند و هیچ فایل Workspace را تغییر نمی‌دهد.</p></div><div className="toolbar"><button className="primary large" onClick={()=>run('persistent-index-scan',{resume:true})} disabled={!root||busy||indexStatus?.status==='unavailable'}>ساخت / ادامه Index</button><button onClick={()=>run('persistent-index-scan',{resume:false})} disabled={!root||busy||indexStatus?.status==='unavailable'}>Fresh Reindex</button><button onClick={()=>run('persistent-index-maintenance',{})} disabled={!root||busy||indexStatus?.status==='unavailable'}>Health + Maintenance</button><button onClick={()=>refreshIndex()} disabled={!root||busy}>Refresh Status</button></div><CycleTimeline cycle={cycle} onConfirm={confirm} onUndo={undo}/>{indexStatus&&<IndexReport data={indexStatus} errors={indexErrors} health={indexHealth}/>}<div className="panel"><h3>Indexed Search</h3><div className="inline"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="مثلاً invoice یا .cdr"/><button className="primary" onClick={()=>run('indexed-file-search',{filters:{query},limit:500})} disabled={!root||busy||['not-indexed','unavailable'].includes(indexStatus?.status)}>جست‌وجو در SQLite</button></div></div>{searchResult&&<SearchRows data={searchResult}/>}</>}
 {tab==='search'&&<><div className="panel"><h3>جست‌وجوی فایل</h3><p>بخشی از نام یا مسیر فایل را بنویسید (مثلاً invoice یا .pdf). برنامه خودش سریع‌ترین روش را انتخاب می‌کند.</p>{!root&&<div className="hint">اول از نوار بالا یک پوشه انتخاب کنید.</div>}<div className="inline"><input value={query} onChange={e=>setQuery(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&root&&!busy&&query.trim())doSearch()}} placeholder="نام یا بخشی از مسیر فایل…"/><button className="primary" onClick={doSearch} disabled={!root||busy||!query.trim()}>{busy?'در حال جست‌وجو…':'جست‌وجو'}</button></div></div><CycleTimeline cycle={cycle} onConfirm={confirm} onUndo={undo}/>{searchResult&&<SearchRows data={searchResult}/>}</>}
 {tab==='cleanup'&&<><div className="grid3"><Task title="حذف فایل‌های زائد" sub="فایل‌های موقت قدیمی‌تر از ۷ روز؛ به قرنطینه می‌روند و برگشت‌پذیرند" on={()=>run('maintenance-cleanup',{includeLowRiskJunk:true})}/><Task title="زائد + پوشه‌های خالی" sub="با پیش‌نمایش قبل از اجرا و امکان بازگردانی" on={()=>run('maintenance-cleanup',{includeLowRiskJunk:true,includeEmptyFolders:true})}/><Task title="فایل‌های خالی (۰ بایت)" sub="فقط قدیمی‌تر از ۳۰ روز" on={()=>run('maintenance-cleanup',{includeLowRiskJunk:true,includeZeroByte:true})}/></div><CycleTimeline cycle={cycle} onConfirm={confirm} onUndo={undo}/></>}
 {tab==='files'&&<><div className="grid2"><Task title="مرتب‌سازی بر اساس نوع فایل" sub="مثلاً عکس‌ها، سندها و ویدیوها در پوشه‌های جدا؛ با پیش‌نمایش و Undo" on={()=>run('organize',{mode:'type'})}/><Task title="مرتب‌سازی بر اساس تاریخ" sub="پوشه‌های سال-ماه؛ با پیش‌نمایش و Undo" on={()=>run('organize',{mode:'date'})}/></div><div className="panel"><h3>تغییر نام گروهی</h3><p>ابتدا پیش‌نمایش نام‌های جدید را می‌بینید؛ فقط با تأیید شما اعمال می‌شود.</p><div className="formgrid"><input placeholder="متنی که باید پیدا شود" value={rename.find} onChange={e=>setRename({...rename,find:e.target.value})}/><input placeholder="با این متن عوض شود" value={rename.replace} onChange={e=>setRename({...rename,replace:e.target.value})}/><input placeholder="پیشوند (اول نام)" value={rename.prefix} onChange={e=>setRename({...rename,prefix:e.target.value})}/><input placeholder="پسوند (آخر نام، قبل از .ext)" value={rename.suffix} onChange={e=>setRename({...rename,suffix:e.target.value})}/><label><input type="checkbox" checked={rename.sequence} onChange={e=>setRename({...rename,sequence:e.target.checked})}/> شماره‌گذاری</label></div><button className="primary" onClick={()=>run('rename',{options:rename})} disabled={!root||busy}>نمایش پیش‌نمایش تغییر نام</button></div><CycleTimeline cycle={cycle} onConfirm={confirm} onUndo={undo}/></>}
 {tab==='duplicates'&&<><div className="panel"><h3>فایل‌های تکراری</h3><p>فایل‌هایی که محتوایشان دقیقاً یکی است پیدا می‌شود. هیچ فایلی خودکار حذف نمی‌شود؛ بعد از دیدن نتیجه می‌توانید نسخه‌های اضافه را به قرنطینه (قابل بازگشت) ببرید.</p>{!root&&<div className="hint">اول از نوار بالا یک پوشه انتخاب کنید.</div>}<div className="actions"><button className="primary large" onClick={findDups} disabled={!root||busy}>{busy?'در حال بررسی…':'پیدا کردن فایل‌های تکراری'}</button>{dup?.groups?.length>0&&<button onClick={()=>run('duplicate-review')} disabled={busy}>پیش‌نمایش انتقال نسخه‌های اضافه به قرنطینه</button>}</div></div><CycleTimeline cycle={cycle} onConfirm={confirm} onUndo={undo}/>{dup&&<div className="panel"><div className="stats"><div><b>{fmt(dup.groupsTotal)}</b><span>گروه</span></div><div><b>{fmt(dup.duplicateFiles)}</b><span>فایل اضافه</span></div><div><b>{bytes(dup.reclaimableBytes)}</b><span>قابل بازیابی</span></div></div>{dup.groups.slice(0,80).map(g=><div className="dup" key={g.id}><div className="dup-head"><b>{bytes(g.size)} · {g.files.length} نسخه</b><span>{bytes(g.reclaimableBytes)}</span></div>{g.files.map(f=><button key={f.path} onClick={()=>api.showItem(f.path)}>{f.path}</button>)}</div>)}</div>}</>}
 {tab==='snapshots'&&<><div className="toolbar"><button className="primary" onClick={()=>run('snapshot')} disabled={!root||busy}>ثبت Snapshot جدید</button><button onClick={()=>run('snapshot-diff')} disabled={!root||busy||!snaps.length}>مقایسه با آخرین Snapshot</button></div><CycleTimeline cycle={cycle} onConfirm={confirm} onUndo={undo}/><div className="panel"><h3>Snapshotهای این Workspace</h3>{snaps.map(s=><div className="snapshot" key={s.id}><b>{s.id}</b><span>{new Date(s.createdAt).toLocaleString('fa-IR')} · {fmt(s.files)} فایل · {bytes(s.bytes)}</span></div>)}{!snaps.length&&<p>هنوز Snapshot ندارید.</p>}</div>{cycle?.type==='snapshot-diff'&&cycle.result&&<Delta d={cycle.result}/>}</>}
 {tab==='automation'&&<><div className="panel"><h3>Automation Rules — Read-only + Condition Watch</h3><p>قرارداد v1: Automation فقط تا وقتی GUI برنامه باز است اجرا می‌شود؛ Background Service و Start-with-Windows به v1.1 موکول شده‌اند. حداقل بازه ۵ دقیقه است و Rule فقط Health / Duplicate / Snapshot / Delta را اجرا می‌کند.</p><div className="formgrid automation-grid"><input value={ruleForm.title} onChange={e=>setRuleForm({...ruleForm,title:e.target.value})} placeholder="عنوان Rule"/><select value={ruleForm.cycleType} onChange={e=>setRuleForm({...ruleForm,cycleType:e.target.value})}><option value="workspace-health">Workspace Health</option><option value="duplicates">Duplicate Scan</option><option value="snapshot">Snapshot</option><option value="snapshot-diff">Snapshot Delta</option></select><input type="number" min="5" value={ruleForm.intervalMinutes} onChange={e=>setRuleForm({...ruleForm,intervalMinutes:Number(e.target.value)})}/><select value={ruleForm.conditionType} onChange={e=>setRuleForm({...ruleForm,conditionType:e.target.value})}><option value="always">بدون شرط</option><option value="free-space-below-percent">Free Space زیر درصد</option><option value="free-space-below-bytes">Free Space زیر GB</option></select>{ruleForm.conditionType!=='always'&&<input type="number" min="1" value={ruleForm.threshold} onChange={e=>setRuleForm({...ruleForm,threshold:Number(e.target.value)})} placeholder={ruleForm.conditionType==='free-space-below-percent'?'درصد':'GB'}/>}<button className="primary" disabled={!root} onClick={async()=>{const condition=ruleForm.conditionType==='always'?{type:'always'}:ruleForm.conditionType==='free-space-below-percent'?{type:ruleForm.conditionType,threshold:ruleForm.threshold}:{type:ruleForm.conditionType,threshold:ruleForm.threshold*1024*1024*1024};await api.automationCreate({root,title:ruleForm.title,cycleType:ruleForm.cycleType,intervalMinutes:ruleForm.intervalMinutes,condition});await refreshRules()}}>ساخت Rule</button></div></div><div className="panel"><h3>Ruleهای فعال</h3>{rules.map(r=><div className="rule" key={r.id}><div><b>{r.title}</b><small>{r.cycleType} · هر {fmt(r.intervalMinutes)} دقیقه · {conditionLabel(r.condition)} · {r.lastStatus||'هنوز اجرا نشده'}</small>{r.lastCondition&&<small>آخرین Condition: {r.lastCondition.detail}</small>}</div><div className="actions"><button onClick={async()=>{const x=await api.automationRun(r.id);if(x.cycle)setCycle(x.cycle);await refreshRules();await refresh()}}>Run / Evaluate</button><button onClick={async()=>{await api.automationUpdate(r.id,{enabled:!r.enabled});await refreshRules()}}>{r.enabled?'Pause':'Resume'}</button><button className="danger" onClick={async()=>{await api.automationRemove(r.id);await refreshRules()}}>حذف Rule</button></div></div>)}{!rules.length&&<p>Rule ساخته نشده است.</p>}</div></>}
 {tab==='recovery'&&<><div className="panel"><div className="panel-title"><div><h3>Crash Recovery Center</h3><p>Transactionهای Write نیمه‌تمام بعد از Restart از روی Source / Staging / Destination طبقه‌بندی می‌شوند. هیچ Recovery خودکار Write نمی‌کند.</p></div><div className="mini-stats"><b>{fmt(recoveries.length)}</b><span>Recoverable</span><b>{journalStatus?.ok?'OK':'Check'}</b><span>Journal Chain</span></div></div><div className="toolbar"><button onClick={async()=>{await refreshRecovery();await refreshJournal()}}>Refresh</button></div>{recoveries.map(tx=><div className="rule" key={tx.id}><div><b>{tx.kind} · {tx.id}</b><small>{tx.status} · {tx.operations.length} عملیات · committed {fmt(tx.recovery.committed)} · staged {fmt(tx.recovery.staged)} · pending {fmt(tx.recovery.pending)}</small><small>{tx.recovery.manualReview?'نیازمند بررسی دستی':`پیشنهاد: ${tx.recovery.recommendation}`}</small></div><div className="actions"><button disabled={!tx.recovery.resumeAllowed} onClick={async()=>{await api.recoveryAct(tx.id,'resume');await refreshRecovery();await refreshJournal()}}>Resume</button><button className="danger" disabled={!tx.recovery.rollbackAllowed} onClick={async()=>{await api.recoveryAct(tx.id,'rollback');await refreshRecovery();await refreshJournal()}}>Rollback</button><button onClick={async()=>{await api.recoveryAct(tx.id,'abandon');await refreshRecovery();await refreshJournal()}}>فقط Archive</button></div></div>)}{!recoveries.length&&<p>Transaction نیمه‌تمامی برای Recovery وجود ندارد.</p>}</div><div className="panel"><h3>Event Journal</h3><p>Hash chain: {journalStatus?.ok?'سالم':'نیازمند بررسی'} · {fmt(journalStatus?.count)} رویداد در فایل فعال</p>{journalRows.slice(0,120).map(e=><div className="file-row" key={`${e.seq}-${e.hash}`}><b>#{fmt(e.seq)} {e.type}</b><span>{e.at} {e.cycleId?`· ${e.cycleId}`:''}</span></div>)}</div></>}
 {tab==='watch'&&<><div className="panel"><h3>File Watcher — Bounded / Coalesced / Volume-aware</h3><p>Eventهای یک Path با هم coalesce می‌شوند، reconcile سریال است و Backpressure سقف‌دار دارد. هنگام Suspend یا قطع Volume، Watcher fail-safe متوقف می‌شود و Root برای Full Reindex علامت می‌خورد.</p><div className="toolbar"><button className="primary" disabled={!root} onClick={async()=>{await api.watchAdd(root);await refreshWatches()}}>Watch همین Workspace</button><button onClick={refreshWatches}>Refresh Events</button><button onClick={async()=>{setResilience(await api.resilienceProbe());await refreshWatches()}}>Probe Storage</button></div>{watchStatus&&<div className="mini-stats"><b>{fmt(watchStatus.pending)}</b><span>Pending</span><b>{fmt(watchStatus.coalesced)}</b><span>Coalesced</span><b>{fmt(watchStatus.droppedDelivery+watchStatus.droppedPending)}</b><span>Backpressure drops</span><b>{watchStatus.suspended?'Paused':'Active'}</b><span>Power state</span></div>}{resilience&&<div className="panel note"><b>Root / Volume Resilience</b>{(resilience.roots||[]).map((r,i)=><div className="file-row" key={`${r.root}-${i}`}><b>{r.status}</b><span>{r.root}{r.driveLetter?` · ${r.driveLetter}:`:''}{r.driveType?` · ${r.driveType}`:''}{r.identityChanged?' · VOLUME ID CHANGED':''}{r.rebindCandidate?.root?` · candidate: ${r.rebindCandidate.root}`:''}</span></div>)}{!(resilience.roots||[]).length&&<p>هنوز Root مانیتورشده‌ای وجود ندارد.</p>}</div>}{watchStatus?.needsFullRescan&&<div className="panel note"><b>Index freshness warning</b><p>برای {fmt(watchStatus.dirtyRoots?.length)} Root بخشی از Watch events از دست رفته/ناموفق بوده است. یک Full Persistent Reindex اجرا کن تا Dirty flag بعد از Commit پاک شود.</p></div>}{watches.map(w=><div className="rule" key={w.id}><div><b>{w.title}</b><small>{w.root}</small></div><div className="actions"><button className="danger" onClick={async()=>{await api.watchRemove(w.id);await refreshWatches()}}>Stop Watch</button></div></div>)}</div><div className="panel"><h3>آخرین File Events</h3>{watchEvents.map(e=><div className="file-row" key={e.id}><b>{e.eventType}</b><span>{e.path}</span></div>)}{!watchEvents.length&&<p>هنوز Event ثبت نشده است.</p>}</div></>}
 {tab==='pdf'&&<><div className="toolbar"><button className="primary large" onClick={()=>run('pdf-intelligence')} disabled={!root||busy}>تحلیل PDFهای Workspace</button><span>Read-only · بدون OCR · Encodingهای پیچیده ممکن است متن کامل ندهند.</span></div><CycleTimeline cycle={cycle} onConfirm={confirm} onUndo={undo}/>{pdfReport&&<div className="panel"><h3>PDF Intelligence</h3><div className="stats"><div><b>{fmt(pdfReport.pdfsFound)}</b><span>PDF found</span></div><div><b>{fmt(pdfReport.processed)}</b><span>Processed</span></div><div><b>{fmt(pdfReport.errorsTotal)}</b><span>Errors</span></div></div>{pdfReport.rows.map(x=><div className="recommend" key={x.path}><div><button className="linkish" onClick={()=>api.showItem(x.path)}>{x.metadata?.title||x.path}</button><small>{fmt(x.pages)} صفحه · {bytes(x.size)} · {x.encrypted?'Encrypted':'Readable base'}</small></div><p>{x.textPreview||'متن پایه استخراج نشد.'}</p><small>{(x.limitations||[]).join(' · ')}</small></div>)}</div>}</>}
 {tab==='cert'&&<div className="health-grid"><div className="panel wide"><div className="panel-title"><div><h3>RC Self‑Check / Runtime Certification</h3><p>Self‑Check داخلی برای RC، جدا از Windows Certification رسمی است. BLOCK می‌تواند Writeها را Fail‑closed کند.</p></div><div className="actions"><button onClick={refreshCert}>Refresh</button><button className="primary" onClick={async()=>{const r=await api.rcSelfCheck(false);setRcCheck(r);setUpdateGuardState(await api.updateGuardStatus())}}>Run Self‑Check</button></div></div>{rcCheck&&<><div className="mini-stats"><b>{String(rcCheck.overall||'-').toUpperCase()}</b><span>RC status</span><b>{fmt(rcCheck.summary?.pass)}</b><span>Pass</span><b>{fmt(rcCheck.summary?.warn)}</b><span>Warn</span><b>{fmt(rcCheck.summary?.block)}</b><span>Block</span></div>{(rcCheck.checks||[]).map(x=><div className="file-row" key={x.id}><b>{x.status.toUpperCase()} · {x.id}</b><span>{x.code} · {x.summary}</span></div>)}</>}{certStatus&&<><div className="meter"><span>Platform</span><b>{certStatus.platform} / {certStatus.arch}</b></div><div className="meter"><span>Node / Electron</span><b>{certStatus.node} / {certStatus.electron||'-'}</b></div><div className="meter"><span>SQLite / Journal</span><b>{certStatus.indexHealth?.ok?'OK':'CHECK'} / {certStatus.journal?.ok?'OK':'CHECK'}</b></div></>}</div><div className="panel"><h3>Version / Update Guard</h3><div className="meter"><span>Current</span><b>{updateGuardState?.currentVersion||'-'}</b></div><div className="meter"><span>Stable</span><b>{updateGuardState?.stableVersion||'-'}</b></div><div className="meter"><span>Pending</span><b>{updateGuardState?.pending?.targetVersion||'-'}</b></div><div className="meter"><span>Writes</span><b>{updateGuardState?.writeBlocked?'BLOCKED':'Allowed'}</b></div><div className="meter"><span>Rollback</span><b>{updateGuardState?.rollbackRecommended?'RECOMMENDED':'-'}</b></div><p>قرارداد Update در v1 دستی و Verified است؛ Downloader/Installer خودکار در RC وجود ندارد. Windows Certification رسمی، Installer/Portable، دو Volume NTFS، Scale و Evidence دستی همچنان باید روی Windows واقعی اجرا شوند.</p></div></div>}
 {tab==='settings'&&<><div className="panel"><h3>Backup / Settings Portability</h3><p>Export تنظیمات برای portability است. State Backup داخلی علاوه بر تنظیمات، Local AI settings و metadata ریشه‌های Index را با SHA256 نگه می‌دارد؛ محتوای Workspace، دیتابیس Index و Secret داخل Backup نیست.</p><div className="actions"><button className="primary" onClick={async()=>{const r=await api.configExport();if(r?.ok)setConfigPreview({mode:'export',...r})}}>Export Settings</button><button onClick={async()=>{const r=await api.configImportPreview();if(r?.ok)setConfigPreview({mode:'import',...r})}}>Import Settings Preview</button>{configPreview?.mode==='import'&&<button className="primary" onClick={async()=>{const r=await api.configImportApply(configPreview.token);setConfigPreview({mode:'applied',...r});await refreshRules();await refreshZones();await refreshWatches()}}>Apply Import</button>}<button onClick={async()=>{const r=await api.stateBackupCreate();setBackupPreview({mode:'created',...r});await refreshBackups()}}>Create State Backup</button><button onClick={async()=>{const r=await api.stateBackupRestorePreview();if(r?.ok)setBackupPreview({mode:'restore',...r})}}>Restore Backup Preview</button>{backupPreview?.mode==='restore'&&<button className="danger" onClick={async()=>{const r=await api.stateBackupRestoreApply(backupPreview.token);setBackupPreview({mode:'restored',...r});await refreshBackups();await refreshRules();await refreshZones();await refreshWatches();await refreshAI()}}>Apply Restore</button>}<button onClick={async()=>setDiagResult(await api.diagnosticsExport())}>Export Redacted Diagnostics</button></div>{configPreview&&<pre className="preview-box">{JSON.stringify(configPreview,null,2)}</pre>}{backupPreview&&<pre className="preview-box">{JSON.stringify(backupPreview,null,2)}</pre>}{diagResult&&<pre className="preview-box">{JSON.stringify(diagResult,null,2)}</pre>}</div><div className="panel"><h3>Local State Backups</h3>{backupRows.map(x=><div className="file-row" key={x.name}><b>{x.name}</b><span>{bytes(x.size)} · {x.updatedAt}</span></div>)}{!backupRows.length&&<p>هنوز State Backup داخلی ساخته نشده است.</p>}</div></>}
 {tab==='cycles'&&<div className="panel"><h3>آخرین چرخه‌ها</h3>{cycles.map(c=><button className="history" key={c.id} onClick={()=>setCycle(c)}><span><b>{c.type}</b><small>{c.id}</small></span><em>{c.status}</em></button>)}<CycleTimeline cycle={cycle} onConfirm={confirm} onUndo={undo}/></div>}
 </main></div>;
 function Task({title,sub,on,disabled}){return <button className="task" onClick={on} disabled={disabled??(!root||busy)}><b>{title}</b><span>{sub}</span></button>}
}
function conditionLabel(c={}){if(!c||c.type==='always')return'بدون شرط';if(c.type==='free-space-below-percent')return`Free < ${c.threshold}%`;if(c.type==='free-space-below-bytes')return`Free < ${bytes(c.threshold)}`;return c.type}
function Health({data}){return <div className="health-grid"><div className="panel score"><h3>Health Score</h3><strong>{fmt(data.healthScore?.score)}/100</strong><p>{data.healthScore?.band}</p></div><div className="panel"><h3>Storage</h3>{data.storage&&<div className="stats vertical"><div><b>{bytes(data.storage.totalBytes)}</b><span>کل</span></div><div><b>{bytes(data.storage.freeBytes)}</b><span>آزاد</span></div></div>}</div><div className="panel wide"><h3>بزرگ‌ترین پوشه‌ها</h3>{data.topFolders.slice(0,30).map(f=><button className="file-row" key={f.path} onClick={()=>api.showItem(f.path)}><b>{bytes(f.bytes)}</b><span>{f.path} · {fmt(f.files)} فایل</span></button>)}</div><div className="panel"><h3>شاخص‌ها</h3><div className="meter"><span>Junk</span><b>{fmt(data.junkTotal)} · {bytes(data.junkBytes)}</b></div><div className="meter"><span>پوشه خالی</span><b>{fmt(data.emptyFoldersTotal)}</b></div><div className="meter"><span>فایل قدیمی</span><b>{fmt(data.stale.total)}</b></div><div className="meter"><span>Zero-byte</span><b>{fmt(data.zeroByte.total)}</b></div><div className="meter"><span>Long path</span><b>{fmt(data.longPaths.total)}</b></div><div className="meter"><span>Unreadable</span><b>{fmt(data.unreadableCount)}</b></div></div><div className="panel"><h3>فایل‌های حجیم</h3>{data.largest.slice(0,30).map(f=><button className="file-row compact" key={f.path} onClick={()=>api.showItem(f.path)}><b>{bytes(f.size)}</b><span>{f.path}</span></button>)}</div></div>}
function Delta({d}){return <div className="panel"><h3>Delta نسبت به Snapshot</h3><div className="stats"><div><b>+{fmt(d.counts.added)}</b><span>Added</span></div><div><b>-{fmt(d.counts.removed)}</b><span>Removed</span></div><div><b>~{fmt(d.counts.modified)}</b><span>Modified</span></div></div>{[...d.added,...d.removed,...d.modified].slice(0,80).map((x,i)=><div className="file-row" key={`${x.rel}-${i}`}><span>{x.path||x.rel}</span></div>)}</div>}
function SystemReport({data}){if(!data.supported)return <div className="panel"><h3>Windows System Doctor</h3><p>این قابلیت هنگام اجرای برنامه روی Windows فعال می‌شود. Runtime فعلی: {data.platform}</p></div>;const adv=data.startupAdvisor;return <div className="health-grid"><div className="panel"><h3>Windows</h3><div className="meter"><span>OS</span><b>{data.os?.caption}</b></div><div className="meter"><span>Build</span><b>{data.os?.build}</b></div><div className="meter"><span>RAM</span><b>{bytes(data.computer?.ramBytes)}</b></div><div className="meter"><span>CPU</span><b>{data.cpu?.name}</b></div></div><div className="panel"><h3>Logical Disks</h3>{(data.disks||[]).map(d=><div className="meter" key={d.DeviceID}><span>{d.DeviceID} {d.VolumeName||''}</span><b>{bytes(d.FreeSpace)} آزاد / {bytes(d.Size)}</b></div>)}</div><div className="panel wide"><div className="panel-title"><div><h3>Startup Review Advisor</h3><p>{adv?.note}</p></div>{adv&&<div className="mini-stats"><b>{fmt(adv.summary.high)}</b><span>High Review</span><b>{fmt(adv.summary.medium)}</b><span>Medium</span></div>}</div>{(adv?.rows||data.startup||[]).slice(0,60).map((x,i)=><div className="startup-row" key={`${x.Name}-${i}`}><div><b>{x.Name}</b><small>{x.Command}</small><p>{(x.evidence||[]).join(' · ')}</p></div>{x.reviewPriority&&<span className={`priority ${x.reviewPriority}`}>{x.reviewPriority}</span>}</div>)}</div><div className="panel wide"><h3>Top Processes by Memory</h3>{(data.topProcesses||[]).map(p=><div className="file-row" key={`${p.Name}-${p.Id}`}><b>{bytes(p.WorkingSet64)}</b><span>{p.Name} · PID {p.Id}</span></div>)}</div></div>}
function ZoneReport({data,zone}){return <div className="health-grid"><div className="panel"><h3>{zone?.title||'Managed Zone'}</h3><div className="meter"><span>Files</span><b>{fmt(data.files)}</b></div><div className="meter"><span>Scanned size</span><b>{bytes(data.bytes)}</b></div><div className="meter"><span>Loose root files</span><b>{fmt(data.looseFiles)}</b></div><div className="meter"><span>Clutter score</span><b>{fmt(data.clutterScore)}/100</b></div></div><div className="panel"><h3>Age / Downloads</h3><div className="meter"><span>&gt; 90 days</span><b>{fmt(data.old90)}</b></div><div className="meter"><span>Partial downloads</span><b>{fmt(data.partialDownloads?.length)}</b></div><div className="meter"><span>Installers</span><b>{fmt(data.installers?.length)}</b></div><div className="meter"><span>Archives</span><b>{fmt(data.archives?.length)}</b></div></div><div className="panel wide"><h3>پیشنهادهای Zone</h3>{(data.recommendations||[]).map(x=><div className="recommend" key={x.code}><div><b>{x.code}</b><small>{fmt(x.count)} مورد</small></div><span className={`priority ${x.priority}`}>{x.priority}</span><p>{x.text}</p></div>)}{!(data.recommendations||[]).length&&<p>هشدار معناداری پیدا نشد.</p>}</div><div className="panel wide"><h3>Storage Trend</h3><div className="trend-list">{(data.trend||[]).slice(-12).map((x,i)=><div className="trend-row" key={`${x.at}-${i}`}><span>{new Date(x.at).toLocaleString('fa-IR')}</span><b>{fmt(x.files)} فایل</b><b>{bytes(x.scannedBytes)}</b><b>{bytes(x.freeBytes)} آزاد</b><b>Clutter {fmt(x.clutterScore)}</b></div>)}</div></div></div>}
function DriveReport({data}){return <div className="health-grid"><div className="panel"><h3>Drive Scope</h3><div className="meter"><span>Root</span><b>{data.root}</b></div><div className="meter"><span>Files scanned</span><b>{fmt(data.scannedFiles)}</b></div><div className="meter"><span>Scanned bytes</span><b>{bytes(data.scannedBytes)}</b></div><div className="meter"><span>Errors</span><b>{fmt(data.errorsTotal)}</b></div></div><div className="panel"><h3>Storage</h3>{data.storage&&<><div className="meter"><span>Total</span><b>{bytes(data.storage.totalBytes)}</b></div><div className="meter"><span>Free</span><b>{bytes(data.storage.freeBytes)}</b></div><div className="meter"><span>Used</span><b>{bytes(data.storage.usedBytes)}</b></div></>}</div><div className="panel wide"><h3>Top folders</h3>{(data.topFolders||[]).slice(0,50).map(f=><button className="file-row" key={f.path} onClick={()=>api.showItem(f.path)}><b>{bytes(f.bytes)}</b><span>{f.path} · {fmt(f.files)} فایل</span></button>)}</div><div className="panel wide"><h3>Large files</h3>{(data.largeFiles||[]).slice(0,60).map(f=><button className="file-row" key={f.path} onClick={()=>api.showItem(f.path)}><b>{bytes(f.size)}</b><span>{f.path}</span></button>)}{!(data.largeFiles||[]).length&&<p>فایل بالاتر از آستانه پیدا نشد.</p>}</div></div>}
function ExplorerResult({data}){if(data?.rows)return <div className="panel"><h3>Explorer Search · {fmt(data.total)} نتیجه</h3><p>{data.source||data.schemaVersion}</p>{data.rows.slice(0,100).map(f=><button className="file-row" key={f.path} onClick={()=>api.showItem(f.path)}><b>{bytes(f.size)}</b><span>{f.relativePath||f.path}</span></button>)}</div>;return <div className="panel"><h3>Explorer Properties</h3><div className="meter"><span>Type</span><b>{data.type||'-'}</b></div><div className="meter"><span>Name</span><b>{data.name||'-'}</b></div><div className="meter"><span>Relative path</span><b>{data.relativePath||'.'}</b></div><div className="meter"><span>Size</span><b>{bytes(data.size)}</b></div><div className="meter"><span>Modified</span><b>{data.mtimeMs?new Date(data.mtimeMs).toLocaleString('fa-IR'):'-'}</b></div><div className="meter"><span>Link/Reparse</span><b>{data.isSymbolicLink?'Yes':'No'}</b></div></div>}
function SearchRows({data}){return <div className="panel"><h3>{fmt(data.total)} نتیجه · {bytes(data.totalBytes)}</h3><p>{data.schemaVersion==='persistent-index-search-v1'?'SQLite Index':'Tree Scan'}{data.hasMore?' · نتایج بیشتر موجود است':''}</p>{(data.rows||[]).map(f=><button className="file-row" key={f.path} onClick={()=>api.showItem(f.path)}><b>{bytes(f.size)}</b><span>{f.path}</span></button>)}</div>}
function IndexReport({data,errors=[],health=null}){return <div className="health-grid"><div className="panel"><h3>Index Status</h3><div className="meter"><span>Status</span><b>{data.status}</b></div><div className="meter"><span>Generation</span><b>{fmt(data.generation)}</b></div><div className="meter"><span>Files</span><b>{fmt(data.files)}</b></div><div className="meter"><span>Indexed bytes</span><b>{bytes(data.bytes)}</b></div></div><div className="panel"><h3>Checkpoint</h3><div className="meter"><span>Queue</span><b>{fmt(data.queue)}</b></div><div className="meter"><span>Dirs seen</span><b>{fmt(data.dirsSeen)}</b></div><div className="meter"><span>Errors</span><b>{fmt(data.errors)}</b></div><div className="meter"><span>Pause reason</span><b>{data.pauseReason||'-'}</b></div>{data.runtime&&<><div className="meter"><span>Root availability</span><b>{data.runtime.status||'-'}</b></div><div className="meter"><span>Volume identity</span><b>{data.runtime.identityChanged?'CHANGED':data.runtime.available?'OK':'OFFLINE'}</b></div></>}</div>{health&&<div className="panel"><h3>SQLite Health</h3><div className="meter"><span>Integrity</span><b>{health.ok?'OK':'CHECK'}</b></div><div className="meter"><span>DB</span><b>{bytes(health.dbBytes)}</b></div><div className="meter"><span>WAL</span><b>{bytes(health.walBytes)}</b></div><div className="meter"><span>Free pages</span><b>{fmt(health.freePages)}</b></div></div>}{errors.length>0&&<div className="panel wide"><h3>آخرین خطاهای Index</h3>{errors.slice(0,40).map((e,i)=><div className="file-row" key={`${e.path}-${i}`}><b>{e.code}</b><span>{e.path}</span></div>)}</div>}</div>}
function Confidence({value}){const n=Math.round(Number(value||0)*100);return <span className={`confidence ${n>=90?'high':n>=72?'medium':'low'}`}>{fmt(n)}%</span>}
function IntelligenceReport({data}){return <div className="health-grid"><div className="panel"><h3>خلاصه Intelligence</h3><div className="meter"><span>Project Candidate</span><b>{fmt(data.summary?.projectCandidates)}</b></div><div className="meter"><span>Destination Suggestion</span><b>{fmt(data.summary?.destinationSuggestions)}</b></div><div className="meter"><span>Rename Suggestion</span><b>{fmt(data.summary?.renameSuggestions)}</b></div><div className="meter"><span>High Confidence</span><b>{fmt(data.summary?.highConfidenceActions)}</b></div></div><div className="panel wide"><h3>پروژه‌های احتمالی</h3>{(data.projects||[]).slice(0,40).map(p=><div className="recommend" key={p.path}><div><b>{p.relativePath}</b><small>{fmt(p.files)} فایل · {bytes(p.bytes)}</small></div><Confidence value={p.confidence}/><p>{(p.evidence||[]).join(' · ')}</p></div>)}</div><div className="panel wide"><h3>پیشنهاد مقصد برای فایل‌های Loose</h3>{(data.destinationSuggestions||[]).slice(0,80).map(x=><div className="recommend" key={x.path}><div><button className="linkish" onClick={()=>api.showItem(x.path)}>{x.name}</button><small>→ {x.suggestedFolder}</small></div><Confidence value={x.confidence}/><p>{(x.evidence||[]).join(' · ')}</p></div>)}{!(data.destinationSuggestions||[]).length&&<p>پیشنهاد قابل اتکایی پیدا نشد.</p>}</div><div className="panel wide"><h3>Rename پیشنهادی از محتوا</h3>{(data.renameSuggestions||[]).slice(0,80).map(x=><div className="recommend" key={x.path}><div><button className="linkish" onClick={()=>api.showItem(x.path)}>{x.currentName}</button><small>→ {x.suggestedName}</small></div><Confidence value={x.confidence}/><p>{(x.evidence||[]).join(' · ')}</p></div>)}{!(data.renameSuggestions||[]).length&&<p>نام generic با عنوان محتوایی مناسب پیدا نشد.</p>}</div></div>}
function UiaReport({data,onAction,busy}){const[selected,setSelected]=useState(null),[action,setAction]=useState('focus'),[value,setValue]=useState('');if(!data.supported)return <div className="panel"><h3>Windows UI Map</h3><p>این قابلیت فقط هنگام اجرای برنامه روی Windows فعال می‌شود. Runtime فعلی: {data.platform}</p></div>;function choose(x){setSelected(x);const t=String(x.controlType||'');if(/Button|MenuItem|Hyperlink/.test(t))setAction('invoke');else if(/CheckBox/.test(t))setAction('toggle');else if(/ComboBox|TreeItem/.test(t))setAction('expand');else if(/Edit|Document/.test(t)&&!x.isPassword)setAction('setValue');else setAction('focus');setValue('')}const allowed=selected?['focus',...(/Button|MenuItem|Hyperlink/.test(String(selected.controlType||''))?['invoke']:[]),...(/CheckBox/.test(String(selected.controlType||''))?['toggle']:[]),...(/ComboBox|TreeItem/.test(String(selected.controlType||''))?['expand','collapse']:[]),...(/Edit|Document/.test(String(selected.controlType||''))&&!selected.isPassword?['setValue']:[])]:[];return <div className="health-grid"><div className="panel"><h3>Focused Window</h3><div className="meter"><span>Name</span><b>{data.focusedWindow?.name||'-'}</b></div><div className="meter"><span>Class</span><b>{data.focusedWindow?.className||'-'}</b></div><div className="meter"><span>Process</span><b>PID {fmt(data.focusedWindow?.processId)}</b></div><div className="meter"><span>Controls</span><b>{fmt(data.elements?.length)} / {fmt(data.totalDescendants)}</b></div></div><div className="panel"><h3>Action Policy</h3><div className="meter"><span>Coordinate Click</span><b>Blocked</b></div><div className="meter"><span>Global Keyboard</span><b>Blocked</b></div><div className="meter"><span>Password</span><b>Blocked</b></div><div className="meter"><span>Execution</span><b>Preview → Confirm → Verify</b></div></div>{selected&&<div className="panel wide uia-composer"><div className="panel-title"><div><h3>Action Preview Builder</h3><p>{selected.name||'(بدون Name)'} · {selected.controlType} · PID {fmt(selected.processId)}</p></div><button className="ghost" onClick={()=>setSelected(null)}>بستن</button></div><div className="formgrid uia-action-grid"><select value={action} onChange={e=>setAction(e.target.value)}>{allowed.map(a=><option key={a} value={a}>{a}</option>)}</select>{action==='setValue'&&<input value={value} onChange={e=>setValue(e.target.value)} maxLength={2048} placeholder="مقدار غیرحساس؛ Password/Secret ممنوع"/>}<button className="primary" disabled={busy||!action||(action==='setValue'&&selected.isPassword)} onClick={()=>onAction(selected,action,value)}>ساخت Preview و درخواست تأیید</button></div><small>Selector با ProcessId + AutomationId/Name/Class/ControlType ساخته می‌شود؛ قبل از Execute دوباره Runtime fingerprint کنترل می‌شود.</small></div>}<div className="panel wide"><h3>Top-level Windows</h3>{(data.windows||[]).slice(0,40).map((x,i)=><div className="file-row" key={`${x.processId}-${x.name}-${i}`}><b>PID {fmt(x.processId)}</b><span>{x.name||'(بدون عنوان)'} · {x.className||x.controlType}</span></div>)}</div><div className="panel wide"><h3>UI Automation Controls</h3>{(data.elements||[]).slice(0,160).map((x,i)=><div className={`uia-row ${selected===x?'selected':''}`} key={`${x.processId}-${x.automationId}-${i}`}><div><b>{x.name||'(بدون Name)'}</b><small>{x.controlType} · id: {x.automationId||'-'} · class: {x.className||'-'}{x.isPassword?' · password':''}</small></div><div className="uia-actions"><span>{x.isOffscreen?'offscreen':x.isEnabled?'enabled':'disabled'}</span><button disabled={!x.isEnabled||x.isOffscreen||x.isPassword} onClick={()=>choose(x)}>انتخاب Action</button></div></div>)}</div></div>}
function SimilarityReport({title,data,kind}){return <div className="panel"><div className="panel-title"><div><h3>{title}</h3><p>{fmt(data.groupsTotal)} گروه · پردازش {fmt(data.processedImages??data.processedFiles)} · خطا {fmt(data.errorsTotal)} · Cache hit {fmt(data.cache?.hits)}</p></div></div>{(data.groups||[]).slice(0,60).map(g=><div className="dup" key={g.id}><div className="dup-head"><b>{fmt(g.files.length)} فایل · فاصله میانگین {g.avgDistance}</b><Confidence value={g.confidence}/></div>{g.files.map(f=><button key={f.path} onClick={()=>api.showItem(f.path)}><span>{f.path}</span>{kind==='text'&&f.profile?.title?<small>{f.profile.title}</small>:null}</button>)}<small>{(g.evidence||[]).join(' · ')}</small></div>)}{!(data.groups||[]).length&&<p>گروه مشابهی با آستانه فعلی پیدا نشد.</p>}</div>}
